#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, U;
    cin >> N >> K >> U;

    vector<vector<int>> cards(N, vector<int>(K));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < K; ++j) {
            cin >> cards[i][j];
        }
    }

    vector<int> pos(U + 1);
    for (int t = 1; t <= U; ++t) {
        int x;
        cin >> x;
        pos[x] = t;
    }

    int best = U + 1;
    vector<int> winners;

    for (int i = 0; i < N; ++i) {
        int finish = 0;
        for (int x : cards[i]) {
            finish = max(finish, pos[x]);
        }

        if (finish < best) {
            best = finish;
            winners.clear();
            winners.push_back(i + 1);
        } else if (finish == best) {
            winners.push_back(i + 1);
        }
    }

    for (int i = 0; i < (int)winners.size(); ++i) {
        if (i > 0) cout << ' ';
        cout << winners[i];
    }
    cout << '\n';

    return 0;
}
